<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>exp02em1b — Protótipo Navegável Lo-Fi: O Efeito Amplificador</title>
  <style>
    :root {
      --superficie-base: #FFFFFF;
      --superficie-elevada: #FAFAFA;
      --superficie-midia: #E0E0E0;
      --borda-padrao: #C7C7C7;
      --borda-foco: #1A1A1A;
      --texto-primario: #1A1A1A;
      --texto-secundario: #6B6B6B;
      --acao-primaria: #1A1A1A;
      --acao-secundaria: #EDEDED;

      /* Tokens da casca de revisão (ferramenta de inspeção externa) */
      --casca-fundo: #0F141C;
      --casca-painel: #1A212D;
      --casca-borda: #2C384A;
      --casca-texto-forte: #F0F4F8;
      --casca-texto-suave: #9BAEC8;
      --casca-acento: #3874CB;
      --casca-acento-hover: #4B88E3;
      --casca-alerta: #D9822B;
      --casca-sucesso: #2E8540;
      --casca-pico: #D9383A;
      --casca-aha: #15B374;
    }

    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background-color: var(--casca-fundo);
      color: var(--casca-texto-forte);
      height: 100vh;
      display: flex;
      flex-direction: column;
      overflow: hidden;
      min-width: 0;
    }

    /* BARRA SUPERIOR */
    header.casca-topo {
      height: 52px;
      background: var(--casca-painel);
      border-bottom: 1px solid var(--casca-borda);
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 16px;
      flex-shrink: 0;
      min-width: 0;
      gap: 12px;
    }

    .topo-info {
      display: flex;
      align-items: center;
      gap: 10px;
      min-width: 0;
      overflow: hidden;
      white-space: nowrap;
    }

    .topo-titulo-missao {
      font-weight: 700;
      font-size: 14px;
      color: var(--casca-texto-forte);
    }

    .topo-etapa-badge {
      background: var(--casca-borda);
      color: var(--casca-texto-forte);
      font-size: 11px;
      font-weight: 600;
      padding: 3px 8px;
      border-radius: 4px;
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }

    .topo-marcas {
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .marca-tag {
      font-size: 11px;
      font-weight: 700;
      padding: 2px 7px;
      border-radius: 3px;
      display: inline-flex;
      align-items: center;
      gap: 4px;
    }

    .marca-pico { background: var(--casca-pico); color: #FFF; }
    .marca-aha { background: var(--casca-aha); color: #FFF; }
    .marca-trava { background: var(--casca-alerta); color: #FFF; }
    .marca-mem { background: #B38600; color: #FFF; }

    .topo-nav {
      display: flex;
      align-items: center;
      gap: 8px;
      flex-shrink: 0;
    }

    .btn-casca {
      background: var(--casca-borda);
      color: var(--casca-texto-forte);
      border: 1px solid transparent;
      padding: 6px 12px;
      border-radius: 4px;
      font-size: 12px;
      font-weight: 600;
      cursor: pointer;
      display: inline-flex;
      align-items: center;
      gap: 6px;
      transition: background 0.15s;
    }

    .btn-casca:hover {
      background: var(--casca-acento);
    }

    .btn-casca:focus-visible {
      outline: 2px solid #FFF;
      outline-offset: 1px;
    }

    .contador-telas {
      font-size: 13px;
      color: var(--casca-texto-suave);
      font-weight: 600;
      min-width: 60px;
      text-align: center;
    }

    /* CORPO PRINCIPAL COM 3 COLUNAS */
    main.casca-corpo {
      flex: 1;
      display: grid;
      grid-template-columns: 280px 1fr 370px;
      overflow: hidden;
      min-width: 0;
    }

    /* COLUNA 1: TRILHO ESQUERDO */
    aside.casca-trilho {
      background: var(--casca-painel);
      border-right: 1px solid var(--casca-borda);
      overflow-y: auto;
      overflow-x: hidden;
      padding: 12px 8px;
      display: flex;
      flex-direction: column;
      gap: 16px;
      min-width: 0;
    }

    .trilho-grupo-titulo {
      font-size: 11px;
      font-weight: 700;
      color: var(--casca-texto-suave);
      text-transform: uppercase;
      letter-spacing: 0.8px;
      padding: 4px 8px;
      margin-bottom: 4px;
      border-bottom: 1px solid var(--casca-borda);
      display: flex;
      justify-content: space-between;
    }

    .trilho-lista {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 2px;
    }

    .trilho-item {
      padding: 7px 8px;
      border-radius: 4px;
      font-size: 12px;
      cursor: pointer;
      display: flex;
      flex-direction: column;
      gap: 2px;
      color: var(--casca-texto-suave);
      border-left: 3px solid transparent;
      transition: all 0.15s;
      min-width: 0;
    }

    .trilho-item:hover {
      background: rgba(255, 255, 255, 0.05);
      color: var(--casca-texto-forte);
    }

    .trilho-item.ativo {
      background: rgba(56, 116, 203, 0.2);
      border-left-color: var(--casca-acento);
      color: var(--casca-texto-forte);
      font-weight: 600;
    }

    .trilho-item-cabecalho {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 6px;
    }

    .trilho-id {
      font-family: monospace;
      font-size: 11px;
      font-weight: 700;
    }

    .trilho-ator {
      font-size: 9px;
      padding: 1px 4px;
      border-radius: 2px;
      background: var(--casca-borda);
      color: #FFF;
      text-transform: uppercase;
    }

    .trilho-estado {
      font-size: 11px;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    /* COLUNA 2: PALCO CENTRAL */
    section.casca-palco {
      background: var(--casca-fundo);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 16px;
      overflow: auto;
      position: relative;
      min-width: 0;
    }

    .palco-moldura-container {
      display: flex;
      flex-direction: column;
      align-items: center;
      max-height: 100%;
    }

    /* MOLDURA MOBILE 375x812 */
    .moldura-mobile {
      width: 375px;
      height: 750px;
      background: var(--superficie-base);
      border: 9px solid var(--borda-padrao);
      border-radius: 36px;
      position: relative;
      overflow: hidden;
      display: flex;
      flex-direction: column;
      box-shadow: 0 16px 36px rgba(0,0,0,0.5);
      flex-shrink: 0;
    }

    /* MOLDURA DESKTOP 1366x768 (ESCALADA) */
    .moldura-desktop {
      width: 820px;
      height: 520px;
      background: var(--superficie-base);
      border: 6px solid var(--borda-padrao);
      border-radius: 12px;
      position: relative;
      overflow: hidden;
      display: flex;
      flex-direction: column;
      box-shadow: 0 16px 36px rgba(0,0,0,0.5);
      flex-shrink: 0;
    }

    .moldura-legenda {
      margin-top: 8px;
      font-size: 11px;
      color: var(--casca-texto-suave);
      text-align: center;
      font-family: monospace;
    }

    /* COLUNA 3: PAINEL DA ETAPA */
    aside.casca-painel-etapa {
      background: var(--casca-painel);
      border-left: 1px solid var(--casca-borda);
      padding: 16px;
      overflow-y: auto;
      display: flex;
      flex-direction: column;
      gap: 16px;
      min-width: 0;
      font-size: 14px;
      line-height: 1.5;
    }

    .painel-secao-titulo {
      font-size: 11px;
      font-weight: 700;
      color: var(--casca-acento);
      text-transform: uppercase;
      letter-spacing: 0.8px;
      margin-bottom: 4px;
    }

    .painel-texto-destaque {
      font-size: 15px;
      font-weight: 600;
      color: var(--casca-texto-forte);
      margin-bottom: 8px;
    }

    .painel-card-info {
      background: rgba(255, 255, 255, 0.04);
      border: 1px solid var(--casca-borda);
      border-radius: 6px;
      padding: 12px;
      font-size: 13px;
      display: flex;
      flex-direction: column;
      gap: 6px;
    }

    .painel-card-info strong {
      color: var(--casca-texto-forte);
    }

    .painel-rodape-fonte {
      margin-top: auto;
      padding-top: 12px;
      border-top: 1px solid var(--casca-borda);
      font-size: 12px;
      color: var(--casca-texto-suave);
      font-style: italic;
    }

    /* RODAPÉ INFORMATIVO */
    footer.casca-rodape {
      height: 48px;
      background: var(--casca-painel);
      border-top: 1px solid var(--casca-borda);
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 16px;
      font-size: 12px;
      flex-shrink: 0;
      min-width: 0;
      gap: 16px;
    }

    .rodape-campo {
      display: flex;
      align-items: center;
      gap: 6px;
      min-width: 0;
      overflow: hidden;
      white-space: nowrap;
      text-overflow: ellipsis;
    }

    .rodape-rotulo {
      color: var(--casca-texto-suave);
      font-weight: 600;
      font-size: 11px;
      text-transform: uppercase;
    }

    .rodape-valor {
      color: var(--casca-texto-forte);
      font-family: monospace;
      font-weight: 600;
    }

    /* =========================================
       SISTEMA VISUAL LO-FI: REGRAS E TOKENS
       (Tudo dentro das molduras obedece 100%
        aos 9 tokens e convenções lo-fi)
       ========================================= */

    .quadro-tela {
      width: 100%;
      height: 100%;
      display: none;
      flex-direction: column;
      background: var(--superficie-base);
      color: var(--texto-primario);
      position: relative;
      overflow-y: auto;
      overflow-x: hidden;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    }

    .quadro-tela.ativo {
      display: flex;
    }

    .marcador-anotacao-estado {
      position: absolute;
      bottom: 4px;
      right: 6px;
      font-size: 10px;
      color: var(--texto-secundario);
      background: rgba(255,255,255,0.85);
      padding: 1px 4px;
      border-radius: 2px;
      pointer-events: none;
      z-index: 99;
      font-family: monospace;
      border: 1px solid var(--borda-padrao);
    }

    /* CHROME SUPERIOR UNOORIAAI */
    .uai-topbar {
      height: 44px;
      border-bottom: 1px solid var(--borda-padrao);
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 12px;
      background: var(--superficie-elevada);
      flex-shrink: 0;
    }

    .uai-topbar-titulo {
      font-size: 13px;
      font-weight: 700;
      color: var(--texto-primario);
    }

    .uai-topbar-menu {
      width: 24px;
      height: 24px;
      border: 1px solid var(--borda-padrao);
      border-radius: 4px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 12px;
    }

    /* CHROME SUPERIOR UNOOVISTA */
    .unv-topbar {
      height: 44px;
      border-bottom: 1px solid var(--borda-padrao);
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 12px;
      background: var(--superficie-base);
      flex-shrink: 0;
    }

    .unv-topbar-logo {
      font-size: 15px;
      font-weight: 800;
      letter-spacing: -0.5px;
    }

    .unv-topbar-acoes {
      display: flex;
      gap: 10px;
    }

    .unv-tabbar {
      height: 48px;
      border-top: 1px solid var(--borda-padrao);
      display: flex;
      align-items: center;
      justify-content: space-around;
      background: var(--superficie-base);
      flex-shrink: 0;
      margin-top: auto;
    }

    .unv-tab-item {
      font-size: 11px;
      font-weight: 600;
      color: var(--texto-secundario);
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 2px;
    }

    .unv-tab-item.ativo {
      color: var(--texto-primario);
    }

    /* ELEMENTOS COMUNS LO-FI */
    .btn-lofi {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 6px;
      padding: 10px 16px;
      border-radius: 6px;
      font-size: 13px;
      font-weight: 600;
      cursor: pointer;
      text-decoration: none;
      transition: all 0.15s;
      border: 1px solid transparent;
      min-height: 40px;
    }

    .btn-lofi-primario {
      background: var(--acao-primaria);
      color: var(--superficie-base);
    }

    .btn-lofi-secundario {
      background: var(--acao-secundaria);
      color: var(--texto-primario);
      border-color: var(--borda-padrao);
    }

    .btn-lofi-desabilitado {
      background: var(--acao-secundaria);
      color: var(--texto-secundario);
      cursor: not-allowed;
      border-color: var(--borda-padrao);
    }

    .card-lofi {
      background: var(--superficie-elevada);
      border: 1px solid var(--borda-padrao);
      border-radius: 8px;
      padding: 14px;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .marcador-midia {
      background: var(--superficie-midia);
      border: 1px solid var(--borda-padrao);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      color: var(--texto-secundario);
      font-size: 11px;
      position: relative;
    }

    .marcador-midia::before, .marcador-midia::after {
      content: "";
      position: absolute;
      top: 0; left: 0; right: 0; bottom: 0;
      background: linear-gradient(to top right, transparent calc(50% - 1px), var(--borda-padrao) calc(50% - 1px), var(--borda-padrao) calc(50% + 1px), transparent calc(50% + 1px));
      pointer-events: none;
    }

    .marcador-midia::after {
      background: linear-gradient(to top left, transparent calc(50% - 1px), var(--borda-padrao) calc(50% - 1px), var(--borda-padrao) calc(50% + 1px), transparent calc(50% + 1px));
    }

    .marcador-legenda {
      z-index: 2;
      background: var(--superficie-elevada);
      padding: 2px 6px;
      border-radius: 3px;
      border: 1px solid var(--borda-padrao);
      font-size: 10px;
    }

    /* CHAT UNOORIAAI */
    .chat-conversa {
      flex: 1;
      padding: 12px;
      display: flex;
      flex-direction: column;
      gap: 12px;
      overflow-y: auto;
    }

    .balao-chat {
      max-width: 85%;
      padding: 10px 12px;
      border-radius: 10px;
      font-size: 13px;
      line-height: 1.4;
    }

    .balao-usuario {
      align-self: flex-end;
      background: var(--superficie-midia);
      color: var(--texto-primario);
      border-bottom-right-radius: 2px;
    }

    .balao-ia {
      align-self: flex-start;
      background: var(--superficie-elevada);
      border: 1px solid var(--borda-padrao);
      color: var(--texto-primario);
      border-bottom-left-radius: 2px;
    }

    .pilulas-prompt {
      display: flex;
      flex-direction: column;
      gap: 6px;
      margin-top: 8px;
    }

    .pilula-item {
      background: var(--superficie-base);
      border: 1px solid var(--borda-padrao);
      padding: 8px 10px;
      border-radius: 16px;
      font-size: 12px;
      color: var(--texto-primario);
      cursor: pointer;
      display: flex;
      align-items: center;
      gap: 6px;
      transition: background 0.15s;
    }

    .pilula-item:hover {
      background: var(--acao-secundaria);
    }

    .chat-input-area {
      padding: 10px;
      border-top: 1px solid var(--borda-padrao);
      background: var(--superficie-elevada);
      display: flex;
      gap: 8px;
      align-items: center;
    }

    .chat-campo {
      flex: 1;
      height: 38px;
      border: 1px solid var(--borda-padrao);
      border-radius: 20px;
      padding: 0 14px;
      font-size: 13px;
      background: var(--superficie-base);
      color: var(--texto-primario);
    }

    /* FEED UNOOVISTA */
    .feed-scroll {
      flex: 1;
      overflow-y: auto;
      display: flex;
      flex-direction: column;
      gap: 12px;
      padding: 12px;
    }

    .postcard-lofi {
      border: 1px solid var(--borda-padrao);
      border-radius: 8px;
      background: var(--superficie-base);
      overflow: hidden;
      display: flex;
      flex-direction: column;
    }

    .postcard-cabecalho {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 10px;
      border-bottom: 1px solid var(--acao-secundaria);
    }

    .perfil-avatar-sim {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      background: var(--superficie-midia);
      border: 1px solid var(--borda-padrao);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 11px;
      font-weight: 700;
    }

    .comentario-item {
      padding: 8px 0;
      border-bottom: 1px solid var(--acao-secundaria);
      display: flex;
      gap: 8px;
      font-size: 12px;
      line-height: 1.4;
    }

    .comentario-conteudo {
      flex: 1;
      display: flex;
      flex-direction: column;
      gap: 2px;
    }

    .comentario-meta {
      display: flex;
      justify-content: space-between;
      color: var(--texto-secundario);
      font-size: 11px;
    }

    /* MENU CONTEXTUAL UNOOVISTA */
    .menu-contextual-modal {
      position: absolute;
      bottom: 0; left: 0; right: 0;
      background: var(--superficie-base);
      border-top: 2px solid var(--borda-foco);
      border-radius: 16px 16px 0 0;
      padding: 16px;
      display: flex;
      flex-direction: column;
      gap: 10px;
      z-index: 50;
      box-shadow: 0 -8px 24px rgba(0,0,0,0.2);
    }

    .menu-item-acao {
      padding: 12px;
      border: 1px solid var(--borda-padrao);
      border-radius: 6px;
      background: var(--superficie-elevada);
      font-size: 13px;
      font-weight: 600;
      cursor: pointer;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .menu-item-acao:hover {
      background: var(--acao-secundaria);
    }

    /* MODAL PADRÃO */
    .modal-sobreposto {
      position: absolute;
      top: 0; left: 0; right: 0; bottom: 0;
      background: rgba(0,0,0,0.6);
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 16px;
      z-index: 60;
    }

    .modal-caixa {
      background: var(--superficie-base);
      border: 2px solid var(--borda-foco);
      border-radius: 12px;
      padding: 18px;
      width: 100%;
      max-width: 330px;
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    /* SELEÇÃO E FOCO */
