      let ulGrupo = null;

      CATALOGO_TELAS.forEach((item, index) => {
        if (item.etapa !== etapaAtual) {
          etapaAtual = item.etapa;
          const tituloGrupo = document.createElement("div");
          tituloGrupo.className = "trilho-grupo-titulo";
          tituloGrupo.innerHTML = `<span>${etapaAtual}</span><span>${item.ator}</span>`;
          trilho.appendChild(tituloGrupo);

          ulGrupo = document.createElement("ul");
          ulGrupo.className = "trilho-lista";
          trilho.appendChild(ulGrupo);
        }

        const li = document.createElement("li");
        li.className = `trilho-item ${index === indiceAtual ? 'ativo' : ''}`;
        li.setAttribute("role", "button");
        li.setAttribute("tabindex", "0");
        li.onclick = () => irParaIndice(index);
        li.onkeydown = (e) => { if (e.key === "Enter" || e.key === " ") irParaIndice(index); };

        li.innerHTML = `
          <div class="trilho-item-cabecalho">
            <span class="trilho-id">${item.id}</span>
            <span class="trilho-ator">${item.ator}</span>
          </div>
          <div class="trilho-estado" title="${item.estado}">${item.estado}</div>
        `;
        ulGrupo.appendChild(li);
      });
    }

